{"path":"packages/cli/src/language-contract.ts","start":15366,"end":16361,"kind":"delivery-boundary","boundary_name":"model-language-staged-only","line_end":403,"raw":"export function createLanguageContractExtension(options: LanguageContractExtensionOptions): LanguageContractExtension {
	const now = options.now ?? (() => new Date());
	const newEpochId = options.newEpochId ?? (() => randomUUID());
	let pi: ExtensionAPI | undefined;
	let active: ActiveLanguageContract | undefined;
	let staged: ActiveLanguageContract | undefined;
	let previous: PromptEpoch | undefined;

	const save = (state: ActiveLanguageContract): PromptEpoch => {
		const epoch = createPromptEpoch({
			contract: state.contract,
			section: state.section,
			source: state.source,
			appliedAt: now(),
			id: newEpochId(),
		});
		state.epoch = epoch;
		const payload: StoredLanguageContractState = {
			version: LANGUAGE_CONTRACT_STATE_VERSION,
			contract: state.contract,
			epoch,
		};
		pi?.appendEntry(LANGUAGE_CONTRACT_ENTRY_TYPE, payload);
		return epoch;
	};

	const commitStaged = (): void => {
		if (!staged) return;
		active = staged;
		staged = undefined;
		save(active);
	};
","role":"model-language-staged-only"}

