{"path":"packages/cli/src/private-fs.ts","start":2930,"end":5055,"kind":"delivery-boundary","boundary_name":"native-private-copy-write","line_end":155,"raw":"export function copyPrivateFile(source: string, destination: string, root: string): void {
	ensurePrivateDirectory(root, dirname(destination));
